package dev.veltraph.client.combat.heal;

import java.util.*;
import org.junit.jupiter.api.Test;
import dev.veltraph.client.combat.ghost.GhostHealReturn;
import dev.veltraph.client.world.Vec3;
import static org.junit.jupiter.api.Assertions.*;

class HealHealthObservationBasisTest {
    private static final Object P=new Object(),W=new Object(),C=new Object();
    private static HealthObservation frame(HealthObservation.Format format,String cue,double hp,double max,float abs,long serial,long at,long epoch){return new HealthObservation(format,cue,hp,max,abs,CapturedHudVitals.Scope.of(P,W,C,epoch),serial,at);}
    private static HealthObservation captured(double hp,long serial,long at){return frame(HealthObservation.Format.CAPTURED_HUD,"E010",hp,1434,0,serial,at,1);}
    @Test void missingOrDifferentSourceNeverSubstitutesNativeHundredOrShieldForCapturedRaw(){var before=captured(1401,1,100);var basis=new HealHealthObservationBasis(before);basis.issued(Optional.of(before),101);assertEquals(1401,basis.health(Optional.empty()));assertEquals(1401,basis.health(Optional.of(frame(HealthObservation.Format.NATIVE_ENTITY,"NATIVE",100,100,99,2,103,1))));assertEquals(0,basis.absorption(Optional.of(frame(HealthObservation.Format.NATIVE_ENTITY,"NATIVE",100,100,99,2,103,1))));}
    @Test void sourceAndNormalStartsUseSameActualBeginSeamAndRawReturnComparison(){for(String caller:List.of("source","normal")){var recovery=new GhostHealReturn();var before=captured(1401,1,100);var basis=HealHealthObservationBasis.begin(recovery,new Vec3(0,70,0),0,0,5,before,100);assertEquals(1401,recovery.pose().health(),caller);assertEquals(GhostHealReturn.Action.CAST,recovery.tick(new Vec3(0,70,0),0,80,basis.health(Optional.empty()),basis.absorption(Optional.empty()),true,true,0,101,0,1000));basis.issued(Optional.of(before),101);assertEquals(GhostHealReturn.Action.NONE,recovery.tick(new Vec3(0,70,0),0,80,basis.health(Optional.empty()),basis.absorption(Optional.empty()),true,true,0,102,0,1000));var after=Optional.of(captured(1450,2,103));assertEquals(GhostHealReturn.Action.RESTORE_VIEW,recovery.tick(new Vec3(0,70,0),0,80,basis.health(after),basis.absorption(after),true,true,0,103,0,1000));assertEquals(GhostHealReturn.State.RESTORE,recovery.state());assertEquals(GhostHealReturn.Action.COMPLETE,recovery.tick(new Vec3(0,70,0),0,0,basis.health(Optional.empty()),basis.absorption(Optional.empty()),true,true,0,104,0,1000));}}
    @Test void newerPostUseSameMaximumEpochAndCueRequiredForEveryFormat(){for(var format:HealthObservation.Format.values()){var before=frame(format,"cue",10,20,0,1,100,1);var basis=new HealHealthObservationBasis(before);basis.issued(Optional.of(before),101);for(var bad:List.of(frame(format,"cue",15,20,0,1,103,1),frame(format,"cue",15,20,0,2,101,1),frame(format,"cue",15,30,0,2,103,1),frame(format,"changed",15,20,0,2,103,1),frame(format,"cue",15,20,0,2,103,2)))assertEquals(10,basis.health(Optional.of(bad)));assertEquals(15,basis.health(Optional.of(frame(format,"cue",15,20,0,2,103,1))));}}
    @Test void legacyAndNativeCannotCrossIntoGlyphOrEachOther(){for(var format:List.of(HealthObservation.Format.LEGACY_HEART,HealthObservation.Format.NATIVE_ENTITY)){var before=frame(format,"cue",10,20,0,1,100,1);var basis=new HealHealthObservationBasis(before);basis.issued(Optional.of(before),101);for(var other:HealthObservation.Format.values())if(other!=format)assertEquals(10,basis.health(Optional.of(frame(other,"cue",15,20,10,2,103,1))));assertEquals(10,basis.health(Optional.empty()));}}
    @Test void nativeHurtMetadataWithUnchangedValuesDoesNotAdvanceAcknowledgment(){var before=frame(HealthObservation.Format.NATIVE_ENTITY,"native",40,40,0,1,100,1);var basis=new HealHealthObservationBasis(before);basis.issued(Optional.of(before),101);var unchanged=Optional.of(frame(HealthObservation.Format.NATIVE_ENTITY,"native",40,40,0,2,103,1));assertEquals(40,basis.health(unchanged));assertEquals(0,basis.absorption(unchanged));}
}
